        public static string FollowUp(string id,bool vietnamese)
        {
            string heading=vietnamese?"Một lượt đã ghi chưa hoàn thành toàn bộ chuỗi khảo sát của bài.\n\n":"One recorded trial does not complete the full investigation.\n\n";
            return heading+(id!=null&&steps.TryGetValue(id,out var pair)?pair[vietnamese?0:1]:vietnamese?"Chưa có hướng dẫn chuỗi so sánh cho mã bài này.":"Comparison-series guidance is unavailable for this lesson ID.");
        }

        // Empty means every catalog lesson has both languages and no foreign lesson IDs were added.
        public static string[] ValidateMetadata()
        {
            var failures=new List<string>();
            foreach(var id in LessonSpec.All.Keys)
                if(!steps.TryGetValue(id,out var pair)||pair==null||pair.Length!=2||string.IsNullOrWhiteSpace(pair[0])||string.IsNullOrWhiteSpace(pair[1]))failures.Add(id);
            foreach(var id in steps.Keys)if(!LessonSpec.All.ContainsKey(id))failures.Add(id+": unknown lesson");
            if(steps.Count!=32)failures.Add("Expected 32 comparison-series entries");
            return failures.ToArray();
        }
    }
}
